use crate::emon::evidence::*;
use crate::emon::oapp::*;

#[test]
fn test_pp_arithmetic_requires_a_source_rule_above_its_total() {
    let rules: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let w: i32 = ow_new(words, 1, 1000, 2000, 1500, 2200, 0, 0, 0, 0, 0, 0, 0, 3, 0, 900, -1);
    crate::testport::assert_eq(pp_total_rule(rules, words, 1, w), 0, "prose has no total rule");
    let other_page: i32 = rl_new(rules, 2, 900, 1900, 1600, 1950, 0);
    rl_set(rules, other_page, rlf_conf(), 1000);
    crate::testport::assert_eq(pp_total_rule(rules, words, 1, w), 0, "another page supplies no rule");
    let short_rule: i32 = rl_new(rules, 1, 1100, 1900, 1400, 1950, 0);
    rl_set(rules, short_rule, rlf_conf(), 1000);
    crate::testport::assert_eq(pp_total_rule(rules, words, 1, w), 0, "a short stroke does not span the total");
    let total_rule: i32 = rl_new(rules, 1, 900, 1900, 1600, 1950, 0);
    rl_set(rules, total_rule, rlf_conf(), 1000);
    crate::testport::assert_eq(pp_total_rule(rules, words, 1, w), 1, "source rule spans the total");
}
